package edu.campusconnect.model;
import jakarta.persistence.*;import java.io.*;import java.util.*;
@Entity @Table(name="student_subjects") @IdClass(StudentSubject.Key.class) public class StudentSubject {@Id @ManyToOne @JoinColumn(name="student_id") public Student student; @Id @ManyToOne @JoinColumn(name="subject_id") public Subject subject; @Enumerated(EnumType.STRING) public StudentSkill.Level proficiency; protected StudentSubject(){} public StudentSubject(Student s,Subject k,StudentSkill.Level l){student=s;subject=k;proficiency=l;} public static class Key implements Serializable {public UUID student;public Long subject;public Key(){} public boolean equals(Object o){return o instanceof Key k && Objects.equals(student,k.student)&&Objects.equals(subject,k.subject);} public int hashCode(){return Objects.hash(student,subject);}}}
